# Generated by termux-geo; static completion, no device or network queries.
# shellcheck shell=bash
_termux_geo() {
  local cur=${COMP_WORDS[COMP_CWORD]} previous=${COMP_WORDS[COMP_CWORD-1]} word prefix='' i mode='' expecting=''
  local fields='latitude longitude coordinates accuracy_m city state state_code postcode county country country_code street house_number address source provider age_seconds cached address_cached stale attribution lat lon zip' options='--json --human --coords --get --format --lat --lon --stdin --provider --refresh --cached --max-age --allow-stale --timeout --language --fields --verbose --color --icons --help' choices=''
  COMPREPLY=()
  for ((i=1;i<COMP_CWORD;i++)); do
    word=${COMP_WORDS[i]}
    if [[ $expecting ]]; then expecting=''; continue; fi
    case $word in
      completion) mode=completion ;;
      get|--get|-g|format|--format|-f|--lat|--lon|--provider|-p|--max-age|--timeout|--language|--color|--icons|--dir) expecting=$word ;;
    esac
  done
  if [[ $cur == --*=* ]]; then previous=${cur%%=*}; prefix=$previous=; cur=${cur#*=}; fi
  case $previous in
    get|--get|-g) choices=$fields ;;
    format|--format|-f)
      local lead='' field
      if [[ $cur == *'{'* ]]; then lead=${cur%\{*}; cur=${cur##*\{}; fi
      for field in $fields; do [[ $field != "$cur"* ]] || COMPREPLY+=("$prefix$lead{$field}"); done
      return ;;
    --provider|-p) choices='network gps passive' ;;
    --color|--icons) choices='auto always never' ;;
    --dir) mapfile -t COMPREPLY < <(compgen -d -- "$cur"); compopt -o filenames 2>/dev/null || : ;;
    --lat|--lon|--max-age|--timeout|--language) return ;;
    *)
      if [[ $mode == completion ]]; then choices='bash zsh fish --install --all --dir --verbose --help'
      else choices="show get format completion $options"; fi ;;
  esac
  [[ ! $choices ]] || mapfile -t COMPREPLY < <(compgen -W "$choices" -- "$cur")
  if [[ $prefix ]]; then for i in "${!COMPREPLY[@]}"; do COMPREPLY[i]=$prefix${COMPREPLY[i]}; done; fi
}
complete -F _termux_geo termux-geo
